package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.identity.*;
import com.ruoyi.medical.persistence.mapper.*;
import java.util.*;
import java.util.function.Function;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Explicit V2 user orchestration with persistence/physical-GET doubles, not real external execution. */
class TaskProfessionalPackageAuthoringV2ServiceTest {
 final PermissionSchema json=new PermissionSchema();final TaskProfessionalPackageAuthoringSchema schema=new TaskProfessionalPackageAuthoringSchema(json).v2();final EnterpriseAccess access=mock(EnterpriseAccess.class);final EnterpriseAccess.Admission a=mock(EnterpriseAccess.Admission.class);final ApplicationSessionIdentity.Verified subject=mock(ApplicationSessionIdentity.Verified.class);
 final TaskProfessionalPackageAuthoringAuthority authority=mock(TaskProfessionalPackageAuthoringAuthority.class);final TaskProfessionalPackageAuthoringLedger ledger=mock(TaskProfessionalPackageAuthoringLedger.class);final TaskProfessionalPackageAuthoringRegistration registrations=mock(TaskProfessionalPackageAuthoringRegistration.class);final TaskProfessionalPackageAuthoringTransport transport=mock(TaskProfessionalPackageAuthoringTransport.class);final TaskProfessionalPackageAuthoringService service;
 final JsonNode request=TaskProfessionalPackageAuthoringV2SchemaTest.request("PROMPT");final String project=TaskProfessionalPackageAuthoringSchemaTest.id(2),key="original-package-key-001";
 final TaskProfessionalPackageAuthoringAuthority.Checked checked=new TaskProfessionalPackageAuthoringAuthority.Checked(json.object().put("current_authority","verified"),new TaskProfessionalPackageAuthoringAuthority.Content(List.of(),List.of()),"INTERNAL");
 TaskProfessionalPackageAuthoringV2ServiceTest()throws Exception{service=new TaskProfessionalPackageAuthoringService(access,schema,authority,ledger,registrations,transport,mock(ArtifactContentService.class),mock(SourceUploadTransport.class),mock(ArtifactRegistryMapper.class),mock(SourceReadMapper.class),mock(DependencyLineage.class),mock(AgentPublicationDependencies.class),mock(EvaluationReferences.class),mock(EvaluationDependencyPolicy.class),json);when(a.context()).thenReturn(new BusinessSessionProtocol.Context(TaskProfessionalPackageAuthoringSchemaTest.id(1),"1","1","1"));when(a.actorId()).thenReturn(TaskProfessionalPackageAuthoringSchemaTest.id(3));when(access.execute(eq(subject),any())).thenAnswer(i->((Function<EnterpriseAccess.Admission,Object>)i.getArgument(1)).apply(a));when(authority.preparation(a,"1",project)).thenReturn(json.object().put("preparation_sha256",TaskProfessionalPackageAuthoringSchemaTest.H));when(authority.check(a,"1",project,request)).thenReturn(checked);when(authority.packageReads(a,project,request)).thenReturn(List.of());}
 TaskProfessionalPackageAuthoringLedger.Original original()throws Exception{var i=json.object().put("tenant_id",a.context().tenant_id()).put("project_id",project).put("created_by",a.actorId()).put("operation_id",TaskProfessionalPackageAuthoringSchemaTest.id(5)).put("kind","PROMPT");i.set("request",request);i.set("authority",checked.proof());i.set("content",json.tree(checked.content()));return new TaskProfessionalPackageAuthoringLedger.Original(i,"a".repeat(64));}
 JsonNode processing(){var n=json.object().put("schema_version","2.0.0").put("state","PROCESSING").put("operation_id",TaskProfessionalPackageAuthoringSchemaTest.id(5)).put("kind","PROMPT").put("production_eligible",false).put("tenant_id",a.context().tenant_id()).put("project_id",project).put("created_by",a.actorId()).put("operation_name","TASK-PROFESSIONAL-PACKAGE").put("target_id",TaskProfessionalPackageAuthoringSchemaTest.id(6)).put("original_key_sha256","a".repeat(64)).put("request_body_sha256","b".repeat(64)).put("request_sha256","c".repeat(64));n.set("schema",schema.descriptor("PROMPT"));n.putNull("artifact");n.putNull("object_version");return n;}
 @Test void existingProcessingOriginalNeverPerformsNewPut()throws Exception{var o=original();when(ledger.byKey(a,key)).thenReturn(o);when(ledger.state(a,o)).thenReturn("PROCESSING");var processing=processing();when(registrations.status(a,o,null)).thenReturn(processing);var result=service.create(subject,"1",project,key,schema.bytes(request));assertEquals(202,result.httpStatus());assertEquals("2",result.body().required("resource_revision").textValue());verifyNoInteractions(transport);verify(ledger,never()).begin(any(),anyString(),anyString(),anyString(),any(),any(),any());}
 @Test void recoveryNotFoundDoesNotFabricateIntentOrTransport()throws Exception{var recovery=json.object().put("schema_version","2.0.0").put("original_key",key);recovery.set("original_request",request);when(registrations.notFound(a,project)).thenReturn(json.object().put("state","NOT_FOUND"));assertEquals(200,service.recover(subject,"1",project,schema.bytes(recovery)).httpStatus());verifyNoInteractions(transport);verify(ledger,never()).begin(any(),anyString(),anyString(),anyString(),any(),any(),any());verify(ledger,never()).recover(any(),any());}
 @Test void revokedCurrentAuthorityBlocksOriginalRecoveryBeforePhysicalGet()throws Exception{var o=original();when(ledger.byKey(a,key)).thenReturn(o);when(ledger.state(a,o)).thenReturn("PROCESSING");when(authority.check(a,"1",project,request)).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));var recovery=json.object().put("schema_version","2.0.0").put("original_key",key);recovery.set("original_request",request);assertThrows(TenantAccessException.class,()->service.recover(subject,"1",project,schema.bytes(recovery)));verifyNoInteractions(transport);verify(ledger,never()).recover(any(),any());}
 @Test void stalePreparationHasDurablePreIntentProofAndNoWriteAttempt()throws Exception{when(authority.preparation(a,"1",project)).thenReturn(json.object().put("preparation_sha256","b".repeat(64)));when(ledger.reject(eq(a),eq("1"),eq(project),eq(key),any(),eq(ErrorCode.SCOPE_STALE))).thenReturn(json.object().put("error_code","SCOPE_STALE").put("outcome","REJECTED_PRE_INTENT"));var result=service.create(subject,"1",project,key,schema.bytes(request));assertEquals(409,result.httpStatus());assertNotNull(result.rejection());verifyNoInteractions(transport);verify(ledger,never()).begin(any(),anyString(),anyString(),anyString(),any(),any(),any());}
 @Test void unknownWriteResponseRetainsOriginalProcessingAndNeverRegisters()throws Exception{var o=original();var attempt=mock(TaskProfessionalPackageAuthoringLedger.Attempt.class);when(attempt.original()).thenReturn(o);when(ledger.begin(eq(a),eq("1"),eq(project),eq(key),eq(request),eq(checked),any())).thenReturn(attempt);when(ledger.state(a,o)).thenReturn("PROCESSING");var processing=processing();when(registrations.status(a,o,null)).thenReturn(processing);when(transport.transfer(eq(subject),eq(attempt),any())).thenThrow(new java.io.IOException("unknown original PUT response"));var result=service.create(subject,"1",project,key,schema.bytes(request));assertEquals(202,result.httpStatus());verify(transport,times(1)).transfer(eq(subject),eq(attempt),any());verify(registrations,never()).register(any(),any(),any());verify(ledger,never()).reject(any(),anyString(),anyString(),anyString(),any(),any());}
 @Test void changedSemanticProofBeforeIntentCannotObtainTransfer()throws Exception{when(authority.check(a,"1",project,request)).thenReturn(checked,new TaskProfessionalPackageAuthoringAuthority.Checked(json.object().put("current_authority","revoked"),checked.content(),"INTERNAL"));assertThrows(TenantAccessException.class,()->service.create(subject,"1",project,key,schema.bytes(request)));verifyNoInteractions(transport);verify(ledger,never()).begin(any(),anyString(),anyString(),anyString(),any(),any(),any());}
}
